#include "ringbuf.h"
#include <stdlib.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;   /* total slots (always > 0) */
    size_t head;       /* next write index */
    size_t tail;       /* next read (oldest) index */
    size_t count;      /* bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head  = 0;
    rb->tail  = 0;
    rb->count = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0 || rb->count == rb->capacity)
        return 0;

    size_t avail = rb->capacity - rb->count;     /* free slots */
    size_t n = (len < avail) ? len : avail;      /* at most what fits */

    /* Write first segment up to end of array, then wrap. */
    size_t rest = rb->capacity - rb->head;        /* space to end */
    size_t first = (n < rest) ? n : rest;

    for (size_t i = 0; i < first; ++i)
        rb->buf[rb->head] = data[i];
    rb->head += first;
    if (rb->head == rb->capacity)
        rb->head = 0;

    /* Write remaining bytes starting at position 0. */
    for (size_t i = first; i < n; ++i) {
        size_t idx = rb->head + (i - first);
        rb->buf[idx] = data[i];
    }
    rb->head += n - first;

    rb->count += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->count == 0)
        return 0;

    size_t n = (len < rb->count) ? len : rb->count;

    size_t rest = rb->capacity - rb->tail;        /* space to end */
    size_t first = (n < rest) ? n : rest;

    for (size_t i = 0; i < first; ++i)
        out[i] = rb->buf[rb->tail];
    rb->tail += first;
    if (rb->tail == rb->capacity)
        rb->tail = 0;

    for (size_t i = first; i < n; ++i) {
        size_t idx = rb->tail + (i - first);
        out[i] = rb->buf[idx];
    }
    rb->tail += n - first;

    rb->count -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->count == 0)
        return 0;

    size_t n = (len < rb->count) ? len : rb->count;

    size_t rest = rb->capacity - rb->tail;        /* space to end */
    size_t first = (n < rest) ? n : rest;

    for (size_t i = 0; i < first; ++i)
        out[i] = rb->buf[rb->tail];
    size_t peek_tail = rb->tail + first;
    if (peek_tail == rb->capacity)
        peek_tail = 0;

    for (size_t i = first; i < n; ++i) {
        size_t idx = peek_tail + (i - first);
        out[i] = rb->buf[idx];
    }

    return n;
}

#include <stdio.h>
#include <assert.h>
#include <string.h>
#include "ringbuf.h"

int main(void)
{
    /* Edge: NULL rb_destroy is OK */
    rb_destroy(NULL);

    /* Edge: invalid create */
    assert(rb_create(0) == NULL);

    ringbuf_t *rb = rb_create(4);
    assert(rb != NULL);
    assert(rb_capacity(rb) == 4);
    assert(rb_size(rb) == 0);

    /* Fill the buffer */
    uint8_t inp[] = {1, 2, 3, 4};
    size_t n = rb_write(rb, inp, 4);
    assert(n == 4);
    assert(rb_size(rb) == 4);

    /* Buffer full: write more returns 0 */
    n = rb_write(rb, inp, 1);
    assert(n == 0);

    /* Peek without removing */
    uint8_t peeked[4];
    assert(rb_peek(rb, peeked, 4) == 4);
    assert(memcmp(peeked, inp, 4) == 0);
    assert(rb_size(rb) == 4);  /* still full */

    /* Read all back */
    uint8_t out[4];
    assert(rb_read(rb, out, 4) == 4);
    assert(memcmp(out, inp, 4) == 0);
    assert(rb_size(rb) == 0);

    /* Write after drain (tests wrap-around from head/tail == capacity) */
    uint8_t more[] = {7, 8};
    assert(rb_write(rb, more, 2) == 2);

    /* Read and write alternately causing many wraps */
    rb_clear(rb);
    for (int i = 0; i < 100; i++) {
        uint8_t b = (uint8_t)(i & 0xFF);
        size_t w = rb_write(rb, &b, 1);
        assert(w == 1);
        if (rb_size(rb) == rb_capacity(rb)) {
            uint8_t r;
            size_t rc = rb_read(rb, &r, 1);
            assert(rc == 1);
            assert(r == (uint8_t)((i - 0) & 0xFF));
        }
    }

    /* Edge: NULL arguments */
    assert(rb_write(NULL, inp, 4) == 0);
    assert(rb_read(NULL, out, 4) == 0);
    assert(rb_peek(NULL, peeked, 4) == 0);
    assert(rb_size(NULL) == 0);
    assert(rb_capacity(NULL) == 0);

    rb_destroy(rb);

    printf("ALL TESTS PASSED\n");
    return 0;
}

